<script setup>import {computed,ref} from 'vue';import {projects} from '../data/portfolio';const filter=ref('All');const categories=['All','Website','Application','UI/UX'];const shown=computed(()=>filter.value==='All'?projects:projects.filter(x=>x.category===filter.value))</script>
<template><section id="projects" class="section"><div class="section-title split"><div><p class="eyebrow">04 — SELECTED WORK</p><h2>Karya yang memadukan<br/><em>fungsi & karakter.</em></h2></div><div class="filters"><button v-for="c in categories" :class="{selected:filter===c}" @click="filter=c">{{c}}</button></div></div><div class="projects-grid"><article v-for="project in shown" :key="project.slug" class="project-card"><RouterLink :to="`/projects/${project.slug}`" class="project-image"><img :src="project.image" :alt="project.title"/><span>View case study <i class="fa-solid fa-arrow-right"/></span></RouterLink><div class="project-info"><div><small>{{project.category}}</small><h3>{{project.title}}</h3></div><RouterLink :to="`/projects/${project.slug}`" aria-label="Lihat proyek"><i class="fa-solid fa-arrow-up-right-from-square"/></RouterLink></div><p>{{project.description}}</p><div class="tags"><span v-for="item in project.tech" :key="item">{{item}}</span></div></article></div></section></template>
